/* 超哥超车 · 数字人语音助手前端
 * VoxEMW 风格 · 独立部署版（GitHub Pages）
 * 协议：OpenAI Realtime 兼容事件 + 自定义 vox.* 事件
 * 连接：WebSocket 到云端服务器（可通过 ?server= 参数指定）
 * 音频：AudioWorklet 16kHz int16 上行；PCM 流式播放
 * 头像：Canvas 动画（眨眼 + 口型同步）
 */
"use strict";
const SAMPLE_RATE = 16000;
// WebSocket 地址：优先 URL 参数，默认使用同源地址
const WS_URL = (() => {
  const p = new URLSearchParams(location.search);
  const s = p.get("server");
  if (s) return s;
  const proto = location.protocol === "https:" ? "wss" : "ws";
  return `${proto}://${location.host}/ws`;
})();
// 头像图片（内嵌base64）
const AVATAR_BASE64 = "";
const AVATAR_PATH = "data:image/jpeg;base64," + AVATAR_BASE64;

// ============================================================
// DOM 元素
// ============================================================
const els = {
  status: document.getElementById("status"),
  canvas: document.getElementById("avatar-canvas"),
  avatarWrap: document.getElementById("avatar-wrap"),
  avatarState: document.getElementById("avatar-state"),
  avatarFallback: document.getElementById("avatar-fallback"),
  transcript: document.getElementById("transcript"),
  micBtn: document.getElementById("mic-btn"),
  camToggle: document.getElementById("cam-toggle"),
  userCam: document.getElementById("user-cam"),
  camWrap: document.getElementById("cam-wrap"),
  overlay: document.getElementById("overlay"),
  startBtn: document.getElementById("start-btn"),
  apiIndicator: document.getElementById("api-indicator"),
};

// ============================================================
// 状态
// ============================================================
let ws = null, mic = null, player = null, camStream = null;
let camOn = false, micOn = false, connected = false;
let assistantLine = null;
let avatarState = "idle"; // idle | listening | thinking | speaking
let avatarImg = null, avatarLoaded = false;

// ============================================================
// Canvas 头像动画
// ============================================================
const W = 512, H = 512;
const ctx = els.canvas.getContext("2d", { alpha: false });
ctx.imageSmoothingEnabled = true;
ctx.imageSmoothingQuality = "high";

let blinkState = 0, blinkTimer = 0;
let mouthOpen = 0, mouthTarget = 0;
let headAngle = 0, headTarget = 0;
let thinkingBrow = 0, thinkingTarget = 0;
let ambientPulse = 0, lastFrameTime = 0;

function loadAvatar() {
  avatarImg = new Image();
  avatarImg.onload = () => { avatarLoaded = true; };
  avatarImg.onerror = () => { avatarLoaded = false; };
  avatarImg.src = AVATAR_PATH;
}

function drawFrame() {
  const now = performance.now();
  const dt = lastFrameTime ? Math.min((now - lastFrameTime) / 1000, 0.1) : 0.016;
  lastFrameTime = now;
  updateAnimation(dt, now);
  renderCanvas();
  requestAnimationFrame(drawFrame);
}

function updateAnimation(dt, now) {
  blinkTimer += dt;
  if (blinkState === 0 && blinkTimer > 2 + Math.random() * 3) blinkState = 1, blinkTimer = 0;
  if (blinkState === 1) blinkState = 2;
  else if (blinkState === 2) blinkState = 0;

  mouthTarget = avatarState === "speaking" ? 0.4 + Math.random() * 0.6
              : avatarState === "thinking" ? 0.05 : 0;
  mouthOpen += (mouthTarget - mouthOpen) * dt * 12;

  thinkingTarget = avatarState === "thinking" ? 1 : 0;
  thinkingBrow += (thinkingTarget - thinkingBrow) * dt * 4;

  headTarget = avatarState === "idle" ? Math.sin(now / 3000) * 0.03 : 0;
  headAngle += (headTarget - headAngle) * dt * 3;

  ambientPulse = (Math.sin(now / 2000) + 1) / 2;
}

function renderCanvas() {
  ctx.fillStyle = "#0d1117";
  ctx.fillRect(0, 0, W, H);

  if (avatarLoaded && avatarImg && avatarImg.complete && avatarImg.naturalWidth > 0) {
    const size = Math.min(W, H) * 0.9, cx = W / 2, cy = H / 2 - 10, s = size / 2;

    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, s, 0, Math.PI * 2);
    ctx.clip();

    const scale = Math.max(size / avatarImg.naturalWidth, size / avatarImg.naturalHeight);
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(headAngle);
    ctx.translate(-cx, -cy);
    ctx.drawImage(avatarImg, cx - (avatarImg.naturalWidth * scale) / 2, cy - (avatarImg.naturalHeight * scale) / 2,
      avatarImg.naturalWidth * scale, avatarImg.naturalHeight * scale);
    ctx.restore();

    // 眨眼
    if (blinkState !== 0) {
      const eyeY = cy - s * 0.1, eyeSp = s * 0.25, eyeH = blinkState === 1 ? s * 0.06 : s * 0.02;
      ctx.fillStyle = "#0d1117";
      ctx.fillRect(cx - eyeSp - s * 0.12, eyeY - eyeH / 2, s * 0.24, eyeH);
      ctx.fillRect(cx + eyeSp - s * 0.12, eyeY - eyeH / 2, s * 0.24, eyeH);
    }

    // 口型
    if (mouthOpen > 0.05) {
      const mouthY = cy + s * 0.25, mw = s * 0.15 + mouthOpen * s * 0.1, mh = mouthOpen * s * 0.12;
      ctx.fillStyle = "#1a0a0a";
      ctx.beginPath();
      ctx.ellipse(cx, mouthY + mh * 0.3, mw / 2, mh / 2, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = "#f0f0f0";
      ctx.beginPath();
      ctx.ellipse(cx, mouthY - mh * 0.15, mw * 0.35, mh * 0.2, 0, 0, Math.PI * 2);
      ctx.fill();
    }

    // 皱眉
    if (thinkingBrow > 0.05) {
      const browY = cy - s * 0.22, browSp = s * 0.25;
      ctx.strokeStyle = "#0d1117";
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(cx - browSp - s * 0.1, browY - s * 0.04 * thinkingBrow);
      ctx.lineTo(cx - browSp + s * 0.1, browY);
      ctx.moveTo(cx + browSp - s * 0.1, browY);
      ctx.lineTo(cx + browSp + s * 0.1, browY - s * 0.04 * thinkingBrow);
      ctx.stroke();
    }
    ctx.restore();

    // 光效
    if (avatarState === "speaking") {
      const g = ctx.createRadialGradient(cx, cy, s * 0.8, cx, cy, s * 1.1);
      g.addColorStop(0, "rgba(233,69,96,0)");
      g.addColorStop(0.5, `rgba(233,69,96,${0.05 + 0.1 * mouthOpen})`);
      g.addColorStop(1, "rgba(233,69,96,0)");
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);
    }
    if (avatarState === "listening") {
      const g = ctx.createRadialGradient(cx, cy, s * 0.9, cx, cy, s * 1.15);
      g.addColorStop(0, "rgba(63,185,80,0)");
      g.addColorStop(0.6, `rgba(63,185,80,${0.05 + 0.05 * ambientPulse})`);
      g.addColorStop(1, "rgba(63,185,80,0)");
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);
    }
  } else {
    drawFallbackAvatar();
  }
}

function drawFallbackAvatar() {
  const cx = W / 2, cy = H / 2;
  ctx.fillStyle = "#1a1a2e";
  ctx.beginPath();
  ctx.arc(cx, cy, 200, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#e94560";
  ctx.beginPath();
  ctx.arc(cx, cy - 30, 60, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(cx, cy + 100, 80, 60, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#fff";
  ctx.font = "28px sans-serif";
  ctx.textAlign = "center";
  ctx.fillText("超哥", cx, cy + 190);
}

function setAvatarState(state) {
  avatarState = state;
  const labels = { idle: "待机中", listening: "聆听中", thinking: "思考中", speaking: "说话中" };
  els.avatarState.textContent = labels[state] || state;
  els.avatarState.className = "avatar-state " + state;
}

// ============================================================
// PCM 编解码
// ============================================================
function floatTo16BitPCM(f32) {
  const i16 = new Int16Array(f32.length);
  for (let i = 0; i < f32.length; i++) {
    const s = Math.max(-1, Math.min(1, f32[i]));
    i16[i] = s < 0 ? s * 0x8000 : s * 0x7fff;
  }
  return i16;
}
function base64FromInt16(i16) {
  const b = new Uint8Array(i16.buffer);
  let bin = "";
  for (let i = 0; i < b.length; i++) bin += String.fromCharCode(b[i]);
  return btoa(bin);
}
function int16FromBase64(b64) {
  const bin = atob(b64);
  const b = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) b[i] = bin.charCodeAt(i);
  return new Int16Array(b.buffer);
}

// ============================================================
// 音频播放
// ============================================================
function ensurePlayer() {
  if (!player) player = { ctx: new AudioContext({ sampleRate: SAMPLE_RATE }), nextStartTime: 0 };
  if (player.ctx.state === "suspended") player.ctx.resume();
  return player;
}
function playPCM(i16) {
  const p = ensurePlayer();
  const buf = p.ctx.createBuffer(1, i16.length, SAMPLE_RATE);
  const d = buf.getChannelData(0);
  for (let i = 0; i < i16.length; i++) d[i] = i16[i] / 0x8000;
  const src = p.ctx.createBufferSource();
  src.buffer = buf;
  src.connect(p.ctx.destination);
  const start = Math.max(p.ctx.currentTime + 0.02, p.nextStartTime);
  src.start(start);
  p.nextStartTime = start + buf.duration;
}
function flushPlayback() {
  if (player) { player.ctx.close(); player = null; }
}

// ============================================================
// 麦克风
// ============================================================
const WORKLET_SRC = `class P extends AudioWorkletProcessor{process(i){const n=i[0];if(n&&n[0]&&n[0].length>0)this.port.postMessage(n[0].slice(0));return true}}registerProcessor("pcm-capture",P);`;

async function startMic() {
  const s = await navigator.mediaDevices.getUserMedia({
    audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true }
  });
  const c = new AudioContext({ sampleRate: SAMPLE_RATE });
  await c.audioWorklet.addModule(URL.createObjectURL(new Blob([WORKLET_SRC], { type: "application/javascript" })));
  const src = c.createMediaStreamSource(s);
  const n = new AudioWorkletNode(c, "pcm-capture");
  n.port.onmessage = e => {
    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify({ type: "input_audio_buffer.append", audio: base64FromInt16(floatTo16BitPCM(e.data)) }));
    }
  };
  src.connect(n);
  const g = c.createGain(); g.gain.value = 0;
  n.connect(g); g.connect(c.destination);
  mic = { ctx: c, stream: s, node: n };
  micOn = true;
}
function stopMic() {
  if (!mic) return;
  mic.node.disconnect();
  mic.stream.getTracks().forEach(t => t.stop());
  mic.ctx.close();
  mic = null;
  micOn = false;
}

// ============================================================
// 转录
// ============================================================
function addLine(cls, who, text) {
  const d = document.createElement("div");
  d.className = "line " + cls;
  if (who) { const s = document.createElement("span"); s.className = "who"; s.textContent = who; d.appendChild(s); }
  d.appendChild(document.createTextNode(text));
  els.transcript.appendChild(d);
  els.transcript.scrollTop = els.transcript.scrollHeight;
  return d;
}
function appendAssistantDelta(d) {
  if (!assistantLine) assistantLine = addLine("assistant", "超哥:", "");
  assistantLine.appendChild(document.createTextNode(d));
  els.transcript.scrollTop = els.transcript.scrollHeight;
}

// ============================================================
// 事件处理
// ============================================================
const handlers = {
  "input_audio_buffer.speech_started"() { flushPlayback(); assistantLine = null; setAvatarState("listening"); },
  "conversation.item.input_audio_transcription.completed"(e) {
    const t = (e.transcript || "").trim();
    if (t) addLine("user", "你:", t);
  },
  "response.output_audio_transcript.delta"(e) { if (e.delta) appendAssistantDelta(e.delta); },
  "response.output_audio_transcript.done"(e) { if (e.transcript) appendAssistantDelta(e.transcript); assistantLine = null; },
  "response.output_audio.delta"(e) { if (e.delta) playPCM(int16FromBase64(e.delta)); },
  "response.audio.delta"(e) { if (e.delta) playPCM(int16FromBase64(e.delta)); },
  "response.done"() { assistantLine = null; setAvatarState("idle"); },
  error(e) { addLine("sys", "", "⚠ " + ((e.error && e.error.message) || "未知错误")); setAvatarState("idle"); },
};

function handleMsg(data) {
  let e;
  try { e = JSON.parse(data); } catch (_) { return; }
  if (e.type === "vox.status") {
    switch (e.status) {
      case "connected":
        connected = true;
        setStatus("已连接", "live");
        els.apiIndicator.textContent = "WS · 已连接";
        els.apiIndicator.classList.add("online");
        els.micBtn.disabled = false;
        els.startBtn.disabled = false;
        els.startBtn.textContent = "🎙 开始通话";
        addLine("sys", "", "已连接到超哥服务器");
        break;
      case "transcribing": case "thinking": setAvatarState("thinking"); break;
      case "speaking": setAvatarState("speaking"); break;
    }
    return;
  }
  const h = handlers[e.type];
  if (h) h(e);
}

// ============================================================
// WebSocket
// ============================================================
function connectWS() {
  if (ws) try { ws.close(); } catch (_) {}
  try { ws = new WebSocket(WS_URL); } catch (_) {
    setStatus("连接失败", "danger");
    els.apiIndicator.textContent = "WS · 失败";
    setTimeout(connectWS, 3000);
    return;
  }
  ws.binaryType = "arraybuffer";
  ws.onopen = () => {
    setStatus("已连接", "live");
    els.apiIndicator.textContent = "WS · 已连接";
    els.apiIndicator.classList.add("online");
    els.micBtn.disabled = false;
    els.startBtn.disabled = false;
    els.startBtn.textContent = "🎙 开始通话";
    addLine("sys", "", "已连接到云端服务器");
  };
  ws.onclose = () => {
    setStatus("已断开", "warn");
    els.apiIndicator.textContent = "WS · 断开";
    els.apiIndicator.classList.remove("online");
    els.micBtn.disabled = true;
    els.startBtn.disabled = true;
    els.startBtn.textContent = "连接中...";
    connected = false;
    setAvatarState("idle");
    setTimeout(connectWS, 3000);
  };
  ws.onerror = () => { setStatus("连接错误", "danger"); els.apiIndicator.textContent = "WS · 错误"; };
  ws.onmessage = m => { if (typeof m.data === "string") handleMsg(m.data); };
}

// ============================================================
// UI
// ============================================================
function setStatus(t, c) { els.status.textContent = t; els.status.className = "status " + (c || ""); }

async function toggleMic() {
  if (micOn) {
    stopMic();
    els.micBtn.textContent = "🎙 开始对话";
    els.micBtn.classList.remove("live");
    setStatus("已连接（麦克风关）", "");
    setAvatarState("idle");
    if (ws && ws.readyState === WebSocket.OPEN) ws.send(JSON.stringify({ type: "response.cancel" }));
  } else {
    try {
      await startMic();
      els.micBtn.textContent = "■ 结束对话";
      els.micBtn.classList.add("live");
      setStatus("聆听中", "live");
      setAvatarState("listening");
    } catch (e) { addLine("sys", "", "⚠ 麦克风不可用: " + e.message); }
  }
}

async function toggleCam() {
  if (camOn) {
    if (camStream) camStream.getTracks().forEach(t => t.stop());
    camStream = null; camOn = false;
    els.camToggle.textContent = "📷 摄像头";
    els.camToggle.classList.remove("live");
    els.userCam.srcObject = null;
    els.camWrap.classList.remove("live");
  } else {
    try {
      camStream = await navigator.mediaDevices.getUserMedia({ video: { width: 320, height: 320, facingMode: "user" } });
      els.userCam.srcObject = camStream;
      camOn = true;
      els.camToggle.textContent = "📷 关闭摄像头";
      els.camToggle.classList.add("live");
      els.camWrap.classList.add("live");
    } catch (e) { addLine("sys", "", "⚠ 摄像头不可用: " + e.message); }
  }
}

// 快捷键
document.addEventListener("keydown", e => {
  if ((e.key === "m" || e.key === "M") && connected) toggleMic();
  if (e.key === "Escape") { if (micOn) toggleMic(); if (camOn) toggleCam(); }
});

// ============================================================
// 初始化
// ============================================================
function init() {
  loadAvatar();
  drawFrame();
  els.startBtn.addEventListener("click", () => { els.overlay.classList.add("hidden"); connectWS(); });
  els.micBtn.addEventListener("click", toggleMic);
  els.camToggle.addEventListener("click", toggleCam);
  setTimeout(() => { if (!connected) connectWS(); }, 500);
}
init();